/**
 * components/aichat/aiMessages.ts
 *
 * Day-40: user-facing copy for the AI panel.
 *
 * The backend reports each rejected AI command as one line of its reply,
 * generated by chat_service (never by the language model):
 *     Rejected EditProperty: value_out_of_range (value must be at most ...).
 * The code and detail are for developers (the backend logs them too); this
 * module replaces such a line with a short explanation for the user and
 * keeps the codes for tests and debugging. Display only: what the backend
 * accepts or rejects is unchanged.
 *
 * Pure: no imports, so it runs under `node --test` without a bundler.
 */

/** Example request shown in the AI input; mm, as the local model handles mm reliably. */
export const AI_EXAMPLE_PROMPT = "Make the selected wall 2800 mm high";

const EXAMPLE = `e.g. "${AI_EXAMPLE_PROMPT}"`;

/** One backend rejection line: `Rejected <CommandType>: <reason_code> (<detail>).` */
const REJECTION_LINE = /^Rejected (\w+): ([a-z_]+) \((.*)\)\.$/;

/** User-facing text per backend RejectionReason (services/commands/contract.py). */
export const REJECTION_MESSAGES: Readonly<Record<string, string>> = {
  value_out_of_range:
    "The proposed value is outside the allowed range for a wall dimension (more than 0 mm and at most 100 m), "
    + `so it was not used. If you gave a size in metres, try millimetres, ${EXAMPLE}.`,
  ambiguous_quantity:
    "The request needs exactly one clear size, written as digits with mm or m. "
    + `Other numbers, ranges or approximate sizes can't be used, ${EXAMPLE}.`,
  no_explicit_quantity: `The request gives no size. State the new dimension as digits with mm or m, ${EXAMPLE}.`,
  relative_change_unsupported: `Relative changes (such as "longer" or "by 10%") aren't supported. State the new size, ${EXAMPLE}.`,
  quantity_mismatch: "The proposed value didn't match the size in the request, so it was not used.",
  unsupported_unit: "Only millimetres (mm) and metres (m) are supported.",
  invalid_value: "The proposed value was not a valid number, so it was not used.",
  no_selection: "No wall is selected. Select a wall, then ask again.",
  target_mismatch: "The proposal was for a different element than the selected wall, so it was not used.",
  unknown_entity: "The proposal referred to an element that doesn't exist, so it was not used.",
  unsupported_target_type: "Only walls can be edited. Select a wall, then ask again.",
  unsupported_entity_reference: "The request mentions another kind of element; only the selected wall can be edited.",
  conflicting_target_reference: "The request names a different element than the selected wall. Select the element you mean, then ask again.",
  unsupported_property: "Only a wall's Length, Height and Thickness can be changed.",
  property_not_present: "Only a wall's Length, Height and Thickness can be changed.",
  no_explicit_property: "Say which dimension to change: high, long or thick.",
  ambiguous_property: "Name only one dimension to change: high, long or thick.",
  property_mismatch: "The proposal changed a different dimension than the request named, so it was not used.",
  stale_proposal: "The wall changed after this was proposed. Ask again to get a new proposal.",
  malformed_command: "The assistant's reply couldn't be used as a wall edit, so it was not used.",
  unsupported_command: "The assistant suggested an action that isn't supported, so it was not used.",
};

/** Shown for a rejection code this version of the frontend doesn't know. */
export const REJECTION_FALLBACK = "The request couldn't be turned into a safe change, so it was not used.";

export interface DisplayedAiText {
  /** Text to show the user. */
  text: string;
  /** Backend rejection codes found in the reply, in order. */
  rejections: string[];
}

/**
 * Turn a backend AI reply into display text: rejection lines become their
 * user-facing message (each message shown once), other lines are kept as
 * they are, and lines are joined as sentences.
 */
export function describeAiReply(text: string): DisplayedAiText {
  const rejections: string[] = [];
  const lines: string[] = [];
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (!line) continue;
    const match = REJECTION_LINE.exec(line);
    if (!match) {
      lines.push(line);
      continue;
    }
    const code = match[2];
    rejections.push(code);
    const message = REJECTION_MESSAGES[code] ?? REJECTION_FALLBACK;
    if (!lines.includes(message)) lines.push(message);
  }
  return { text: lines.map((l) => (/[.!?]$/.test(l) ? l : `${l}.`)).join(" "), rejections };
}
